hp" class="methodname" style="color:#CC7832">remove</a></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span> <span class="parameter" style="color:#3A95FF">\$key</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span> <span class="parameter" style="color:#3A95FF">\$default</span><span class="initializer"> = ?</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/ds-map.reverse.php" class="methodname" style="color:#CC7832">reverse</a></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/ds-map.reversed.php" class="methodname" style="color:#CC7832">reversed</a></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.ds-map.php" class="type Ds\Map" style="color:#EAB766">Ds\Map</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/ds-map.skip.php" class="methodname" style="color:#CC7832">skip</a></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span> <span class="parameter" style="color:#3A95FF">\$position</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.ds-pair.php" class="type Ds\Pair" style="color:#EAB766">Ds\Pair</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/ds-map.slice.php" class="methodname" style="color:#CC7832">slice</a></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span> <span class="parameter" style="color:#3A95FF">\$index</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span> <span class="parameter" style="color:#3A95FF">\$length</span><span class="initializer"> = ?</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.ds-map.php" class="type Ds\Map" style="color:#EAB766">Ds\Map</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/ds-map.sort.php" class="methodname" style="color:#CC7832">sort</a></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.callable.php" class="type callable" style="color:#EAB766">callable</a></span> <span class="parameter" style="color:#3A95FF">\$comparator</span><span class="initializer"> = ?</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.void.php" class="type void" style="color:#EAB766">void</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/ds-map.sorted.php" class="methodname" style="color:#CC7832">sorted</a></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.callable.php" class="type callable" style="color:#EAB766">callable</a></span> <span class="parameter" style="color:#3A95FF">\$comparator</span><span class="initializer"> = ?</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.ds-map.php" class="type Ds\Map" style="color:#EAB766">Ds\Map</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/ds-map.sum.php" class="methodname" style="color:#CC7832">sum</a></span>(): <span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.float.php" class="type float" style="color:#EAB766">float</a></span></span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/ds-map.toarray.php" class="methodname" style="color:#CC7832">toArray</a></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/ds-map.union.php" class="methodname" style="color:#CC7832">union</a></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.ds-map.php" class="type Ds\Map" style="color:#EAB766">Ds\Map</a></span> <span class="parameter" style="color:#3A95FF">\$map</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.ds-map.php" class="type Ds\Map" style="color:#EAB766">Ds\Map</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/ds-map.values.php" class="methodname" style="color:#CC7832">values</a></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.ds-sequence.php" class="type Ds\Sequence" style="color:#EAB766">Ds\Sequence</a></span></div><div class="methodsynopsis dc-description"><span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/ds-map.xor.php" class="methodname" style="color:#CC7832">xor</a></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.ds-map.php" class="type Ds\Map" style="color:#EAB766">Ds\Map</a></span> <span class="parameter" style="color:#3A95FF">\$map</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.ds-map.php" class="type Ds\Map" style="color:#EAB766">Ds\Map</a></span></div>   }</div>  </div>  <div class="section" id="ds-map.constants">   <h2 class="title">预定义常量</h2>   <dl>         <dt id="ds-map.constants.min-capacity"><strong><span>{@link Ds\Map::MIN_CAPACITY}</span></strong></dt>     <dd>      <p class="para"></p>     </dd>       </dl>  </div>  <div class="section">   <h2 class="title">更新日志</h2>   <p class="para">    </p><table class="doctable informaltable">           <thead>       <tr>        <th>版本</th>        <th>说明</th>       </tr>      </thead>      <tbody class="tbody">       <tr>        <td>PECL ds 1.3.0</td>        <td>         The class now implements <span class="classname"><a href="https://php.net/manual/zh/class.arrayaccess.php" class="classname">ArrayAccess</a></span>.        </td>       </tr>       <tr>        <td>PECL ds 1.2.0</td>        <td>         <strong><span>{@link Ds\Map::MIN_CAPACITY}</span></strong> changed from 16 to 8.        </td>       </tr>      </tbody>         </table>     </div> </div> <h2>目录</h2><ul class="chunklist chunklist_reference"><li>{@link Ds\Map::allocate} — Allocates enough memory for a required capacity</li><li>{@link Ds\Map::apply} — Updates all values by applying a callback function to each value</li><li>{@link Ds\Map::capacity} — Returns the current capacity</li><li>{@link Ds\Map::clear} — Removes all values</li><li>{@link Ds\Map::__construct} — Creates a new instance</li><li>{@link Ds\Map::copy} — Returns a shallow copy of the map</li><li>{@link Ds\Map::count} — Returns the number of values in the map</li><li>{@link Ds\Map::diff} — Creates a new map using keys that aren't in another map</li><li>{@link Ds\Map::filter} — Creates a new map using a callable to determine which pairs to include</li><li>{@link Ds\Map::first} — Returns the first pair in the map</li><li>{@link Ds\Map::get} — Returns the value for a given key</li><li>{@link Ds\Map::hasKey} — Determines whether the map contains a given key</li><li>{@link Ds\Map::hasValue} — Determines whether the map contains a given value</li><li>{@link Ds\Map::intersect} — Creates a new map by intersecting keys with another map</li><li>{@link Ds\Map::isEmpty} — Returns whether the map is empty</li><li>{@link Ds\Map::jsonSerialize} — Returns a representation that can be converted to JSON</li><li>{@link Ds\Map::keys} — Returns a set of the map's keys</li><li>{@link Ds\Map::ksort} — Sorts the map in-place by key</li><li>{@link Ds\Map::ksorted} — Returns a copy, sorted by key</li><li>{@link Ds\Map::last} — Returns the last pair of the map</li><li>{@link Ds\Map::map} — Returns the result of applying a callback to each value</li><li>{@link Ds\Map::merge} — Returns the result of adding all given associations</li><li>{@link Ds\Map::pairs} — Returns a sequence containing all the pairs of the map</li><li>{@link Ds\Map::put} — Associates a key with a value</li><li>{@link Ds\Map::putAll} — Associates all key-value pairs of a traversable object or array</li><li>{@link Ds\Map::reduce} — Reduces the map to a single value using a callback function</li><li>{@link Ds\Map::remove} — Removes and returns a value by key</li><li>{@link Ds\Map::reverse} — Reverses the map in-place</li><li>{@link Ds\Map::reversed} — Returns a reversed copy</li><li>{@link Ds\Map::skip} — Returns the pair at a given positional index</li><li>{@link Ds\Map::slice} — Returns a subset of the map defined by a starting index and length</li><li>{@link Ds\Map::sort} — Sorts the map in-place by value</li><li>{@link Ds\Map::sorted} — Returns a copy, sorted by value</li><li>{@link Ds\Map::sum} — Returns the sum of all values in the map</li><li>{@link Ds\Map::toArray} — Converts the map to an array</li><li>{@link Ds\Map::union} — Creates a new map using values from the current instance and another map</li><li>{@link Ds\Map::values} — Returns a sequence of the map's values</li><li>{@link Ds\Map::xor} — Creates a new map using keys of either the current instance or of another map, but not of both</li></ul></div>
 * 
 * @template TKey
 * @template TValue
 */
interface Map extends \Traversable {
/**
 * <div id="ds-map.pairs" class="refentry"> <div class="refnamediv">  <h1 class="refname">Ds\Map::pairs</h1>  <p class="verinfo">(PECL ds &gt;= 1.0.0)</p><p class="refpurpose"><span class="refname">Ds\Map::pairs</span> — <span class="dc-title">Returns a sequence containing all the pairs of the map</span></p> </div> <div class="refsect1 description" id="refsect1-ds-map.pairs-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Ds\Map::pairs</strong></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.ds-sequence.php" class="type Ds\Sequence" style="color:#EAB766">Ds\Sequence</a></span></div>  <p class="para rdfs-comment">    Returns a <span class="classname"><a href="https://php.net/manual/zh/class.ds-sequence.php" class="classname">Ds\Sequence</a></span> containing all the pairs of the map.  </p> </div> <div class="refsect1 parameters" id="refsect1-ds-map.pairs-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-ds-map.pairs-returnvalues">  <h3 class="title">返回值</h3>  <p class="para">    <span class="classname"><a href="https://php.net/manual/zh/class.ds-sequence.php" class="classname">Ds\Sequence</a></span> containing all the pairs of the map.  </p> </div> <div class="refsect1 examples" id="refsect1-ds-map.pairs-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">Ds\Map::pairs()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$map </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Ds\Map</span><span style="color: #007700">([</span><span style="color: #DD0000">"a" </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">1</span><span style="color: #007700">, </span><span style="color: #DD0000">"b" </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">2</span><span style="color: #007700">, </span><span style="color: #DD0000">"c" </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">3</span><span style="color: #007700">]);<br><br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$map</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">pairs</span><span style="color: #007700">());<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">object(Ds\Vector)#8&nbsp;(3)&nbsp;{<br>&nbsp;&nbsp;[0]=&gt;<br>&nbsp;&nbsp;object(Ds\Pair)#5&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;&nbsp;&nbsp;["key"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;string(1)&nbsp;"a"<br>&nbsp;&nbsp;&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;int(1)<br>&nbsp;&nbsp;}<br>&nbsp;&nbsp;[1]=&gt;<br>&nbsp;&nbsp;object(Ds\Pair)#6&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;&nbsp;&nbsp;["key"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;string(1)&nbsp;"b"<br>&nbsp;&nbsp;&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;int(2)<br>&nbsp;&nbsp;}<br>&nbsp;&nbsp;[2]=&gt;<br>&nbsp;&nbsp;object(Ds\Pair)#7&nbsp;(2)&nbsp;{<br>&nbsp;&nbsp;&nbsp;&nbsp;["key"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;string(1)&nbsp;"c"<br>&nbsp;&nbsp;&nbsp;&nbsp;["value"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;int(3)<br>&nbsp;&nbsp;}<br>}</blockquote></div>   </div>  </div> </div></div>
 */
  public function pairs(): iterable;
  /**
 * <div id="ds-map.get" class="refentry"> <div class="refnamediv">  <h1 class="refname">Ds\Map::get</h1>  <p class="verinfo">(PECL ds &gt;= 1.0.0)</p><p class="refpurpose"><span class="refname">Ds\Map::get</span> — <span class="dc-title">Returns the value for a given key</span></p> </div> <div class="refsect1 description" id="refsect1-ds-map.get-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>Ds\Map::get</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span> <span class="parameter" style="color:#3A95FF">\$key</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span> <span class="parameter" style="color:#3A95FF">\$default</span><span class="initializer"> = ?</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.mixed.php" class="type mixed" style="color:#EAB766">mixed</a></span></div>  <p class="para rdfs-comment">    Returns the value for a given key, or an optional default value if the key    could not be found.  </p>  <blockquote class="note" style="border:1px gray solid"><p><strong class="note" style="border:1px gray solid">注意</strong>:     </p><p class="para">        Keys of type <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.object.php" class="type object" style="color:#EAB766">object</a></span> are supported.        If an object implements <span class="classname"><a href="https://php.net/manual/zh/class.ds-hashable.php" class="classname">Ds\Hashable</a></span>,        equality will be determined by the object's <span class="code">equals</span> function.        If an object does not implement <span class="classname"><a href="https://php.net/manual/zh/class.ds-hashable.php" class="classname">Ds\Hashable</a></span>,        objects must be references to the same instance to be considered equal.    </p>  </blockquote>  <blockquote class="note" style="border:1px gray solid"><p><strong class="note" style="border:1px gray solid">注意</strong>:     </p><p class="para">        You can also use array syntax to access values by key, eg. <span class="code">\$map["key"]</span>.    </p>  </blockquote>  <div class="caution"><strong class="caution">警告</strong>    <p class="para">        Be careful when using array syntax. Scalar keys will be coerced to        integers by the engine. For example, <span class="code">\$map["1"]</span> will attempt        to access <span class="code">int(1)</span>, while <span class="code">\$map-&gt;get("1")</span> will        correctly look up the string key.    </p>    <p class="para">        See <a href="https://php.net/manual/zh/language.types.array.php" class="link">Arrays</a>.    </p>  </div> </div> <div class="refsect1 parameters" id="refsect1-ds-map.get-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">key</span></dt>    <dd>     <p class="para">        The key to look up.     </p>    </dd>          <dt><span class="parameter" style="color:#3A95FF">default</span></dt>    <dd>     <p class="para">        The optional default value, returned if the key could not be found.     </p>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-ds-map.get-returnvalues">  <h3 class="title">返回值</h3>  <p class="para">    The value mapped to the given <span class="parameter" style="color:#3A95FF">key</span>, or the <span class="parameter" style="color:#3A95FF">default</span>    value if provided and the key could not be found in the map.  </p> </div> <div class="refsect1 errors" id="refsect1-ds-map.get-errors">  <h3 class="title">错误／异常</h3>  <p class="para">   <span class="classname"><a href="https://php.net/manual/zh/class.outofboundsexception.php" class="classname">OutOfBoundsException</a></span> if the key could not be found   and a default value was not provided.  </p> </div> <div class="refsect1 examples" id="refsect1-ds-map.get-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">Ds\Map::get()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$map </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Ds\Map</span><span style="color: #007700">([</span><span style="color: #DD0000">"a" </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">1</span><span style="color: #007700">, </span><span style="color: #DD0000">"b" </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">2</span><span style="color: #007700">, </span><span style="color: #DD0000">"c" </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">3</span><span style="color: #007700">]);<br><br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$map</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">get</span><span style="color: #007700">(</span><span style="color: #DD0000">"a"</span><span style="color: #007700">));       </span><span style="color: #FF8000">// 1<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$map</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">get</span><span style="color: #007700">(</span><span style="color: #DD0000">"d"</span><span style="color: #007700">, </span><span style="color: #9876AA">10</span><span style="color: #007700">));   </span><span style="color: #FF8000">// 10 (default used)<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">int(1)<br>int(10)</blockquote></div>   </div>  </div>  <div class="example" id="example-2">   <p><strong>示例 #2 <span class="function"><strong style="color:#CC7832">Ds\Map::get()</strong></span> example using array syntax</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$map </span><span style="color: #007700">= new </span><span style="color: #9876AA">\Ds\Map</span><span style="color: #007700">([</span><span style="color: #DD0000">"a" </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">1</span><span style="color: #007700">, </span><span style="color: #DD0000">"b" </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">2</span><span style="color: #007700">, </span><span style="color: #DD0000">"c" </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">3</span><span style="color: #007700">]);<br><br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$map</span><span style="color: #007700">[</span><span style="color: #DD0000">"a"</span><span style="color: #007700">]); </span><span style="color: #FF8000">// 1<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">int(1)</blockquote></div>   </div>  </div> </div></div>
